package com.travelbird.trip;
import static org.assertj.core.api.Assertions.*;
import com.travelbird.support.MySqlContainerSupport; import javax.sql.DataSource; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.jdbc.core.*; import org.springframework.test.context.ActiveProfiles;
@ActiveProfiles("test") @SpringBootTest @Tag("mysql-integration")
class TripSchemaMySqlIntegrationTest extends MySqlContainerSupport {
 @Autowired jakarta.persistence.EntityManagerFactory emf; @Autowired com.travelbird.trip.service.TripService service; private final JdbcTemplate jdbc; @Autowired TripSchemaMySqlIntegrationTest(DataSource ds){jdbc=new JdbcTemplate(ds);}
 @Test void v7EnforcesTripWidePlaceAndDayOrderUniqueness(){assertThat(jdbc.queryForObject("select count(*) from flyway_schema_history where version='7' and success=1",Integer.class)).isEqualTo(1);long uid=insert("insert into users(email,status,role,onboarding_completed) values('trip@test','ACTIVE','ROLE_USER',false)");long trip=insert("insert into trips(user_id,source_type,title,sigungu_code,start_date,end_date,companion_type,pace,visibility) values("+uid+",'MANUAL','t','11110','2026-09-08','2026-09-09','SOLO','NORMAL','PRIVATE')");long d1=insert("insert into trip_days(trip_id,day_number) values("+trip+",1)");long d2=insert("insert into trip_days(trip_id,day_number) values("+trip+",2)");long p=insert("insert into places(status,name,category,address,sigungu_code,latitude,longitude) values('ACTIVE','p','ATTRACTION','a','11110',37,127)");jdbc.update("insert into trip_places(trip_id,trip_day_id,place_id,visit_order) values(?,?,?,1)",trip,d1,p);assertThatThrownBy(()->jdbc.update("insert into trip_places(trip_id,trip_day_id,place_id,visit_order) values(?,?,?,1)",trip,d2,p)).isInstanceOf(DataIntegrityViolationException.class);}
 @Test void dayOrderWishlistAndCompositeOwnershipConstraintsHold(){long uid=insert("insert into users(email,status,role,onboarding_completed) values('trip2@test','ACTIVE','ROLE_USER',false)");long t1=insert("insert into trips(user_id,source_type,title,sigungu_code,start_date,end_date,companion_type,pace,visibility) values("+uid+",'MANUAL','t1','11110','2026-09-08','2026-09-09','SOLO','NORMAL','PRIVATE')");long t2=insert("insert into trips(user_id,source_type,title,sigungu_code,start_date,end_date,companion_type,pace,visibility) values("+uid+",'MANUAL','t2','11110','2026-09-08','2026-09-09','SOLO','NORMAL','PRIVATE')");long d1=insert("insert into trip_days(trip_id,day_number) values("+t1+",1)");long d2=insert("insert into trip_days(trip_id,day_number) values("+t2+",1)");long p1=insert("insert into places(status,name,category,address,sigungu_code,latitude,longitude) values('ACTIVE','p1','ATTRACTION','a','11110',37,127)");long p2=insert("insert into places(status,name,category,address,sigungu_code,latitude,longitude) values('ACTIVE','p2','ATTRACTION','a','11110',37,127)");jdbc.update("insert into trip_places(trip_id,trip_day_id,place_id,visit_order) values(?,?,?,1)",t1,d1,p1);assertThatThrownBy(()->jdbc.update("insert into trip_places(trip_id,trip_day_id,place_id,visit_order) values(?,?,?,1)",t1,d1,p2)).isInstanceOf(DataIntegrityViolationException.class);assertThatThrownBy(()->jdbc.update("insert into trip_places(trip_id,trip_day_id,place_id,visit_order) values(?,?,?,2)",t1,d2,p2)).isInstanceOf(DataIntegrityViolationException.class);jdbc.update("insert into trip_wishlist_places(trip_id,place_id) values(?,?)",t1,p2);assertThatThrownBy(()->jdbc.update("insert into trip_wishlist_places(trip_id,place_id) values(?,?)",t1,p2)).isInstanceOf(DataIntegrityViolationException.class);}
 @Test void optimisticVersionCompareAndSetAllowsOnlyOneWriter(){long uid=insert("insert into users(email,status,role,onboarding_completed) values('trip3@test','ACTIVE','ROLE_USER',false)");long trip=insert("insert into trips(user_id,source_type,title,sigungu_code,start_date,end_date,companion_type,pace,visibility) values("+uid+",'MANUAL','t','11110','2026-09-08','2026-09-09','SOLO','NORMAL','PRIVATE')");assertThat(jdbc.update("update trips set title='first',version=version+1 where trip_id=? and version=0",trip)).isOne();assertThat(jdbc.update("update trips set title='second',version=version+1 where trip_id=? and version=0",trip)).isZero();} @Test void jpaVersionRejectsStaleAggregateUpdate(){long uid=insert("insert into users(email,status,role,onboarding_completed) values('trip4@test','ACTIVE','ROLE_USER',false)");long tripId=insert("insert into trips(user_id,source_type,title,sigungu_code,start_date,end_date,companion_type,pace,visibility) values("+uid+",'MANUAL','t','11110','2026-09-08','2026-09-09','SOLO','NORMAL','PRIVATE')");var first=emf.createEntityManager();var stale=emf.createEntityManager();try{first.getTransaction().begin();stale.getTransaction().begin();var a=first.find(com.travelbird.trip.entity.Trip.class,tripId);var b=stale.find(com.travelbird.trip.entity.Trip.class,tripId);a.updateBasic("first",true,null,false,null,false,null,false,null,false,null,false);b.updateBasic("stale",true,null,false,null,false,null,false,null,false,null,false);first.getTransaction().commit();assertThatThrownBy(()->stale.getTransaction().commit()).isInstanceOf(jakarta.persistence.RollbackException.class);}finally{first.close();stale.close();}}
 @Test void serviceRejectsWishlistPlaceAlreadyScheduled(){long uid=insert("insert into users(email,status,role,onboarding_completed) values('trip5@test','ACTIVE','ROLE_USER',false)");long trip=insert("insert into trips(user_id,source_type,title,sigungu_code,start_date,end_date,companion_type,pace,visibility) values("+uid+",'MANUAL','t','11110','2026-09-08','2026-09-09','SOLO','NORMAL','PRIVATE')");long day=insert("insert into trip_days(trip_id,day_number) values("+trip+",1)");long place=insert("insert into places(status,name,category,address,sigungu_code,latitude,longitude) values('ACTIVE','scheduled','ATTRACTION','a','11110',37,127)");jdbc.update("insert into trip_places(trip_id,trip_day_id,place_id,visit_order) values(?,?,?,1)",trip,day,place);assertThatThrownBy(()->service.addWishlist(uid,trip,new com.travelbird.trip.dto.request.WishlistPlaceRequest(place))).isInstanceOfSatisfying(com.travelbird.global.error.BusinessException.class,e->assertThat(e.errorCode()).isEqualTo(com.travelbird.global.error.ErrorCode.PLACE_ALREADY_ASSIGNED_TO_DAY));} private long insert(String sql){var kh=new org.springframework.jdbc.support.GeneratedKeyHolder();jdbc.update(c->{var ps=c.prepareStatement(sql,java.sql.Statement.RETURN_GENERATED_KEYS);return ps;},kh);return kh.getKey().longValue();}
}
